arguments.old:
// Blade tenon below the shoulder: 24 x 34 with 4 mm corner radii,
// so it clears the post socket's 5 mm rounded corners. It reaches
// 2 mm up into the neck so the union is volumetric, not face-only.
translate([0, 0, hang_width/2]) rotate([-90, 0, 0])
    linear_extrude(hang_shoulder_rel + 2)
        rounded_rect(2*hang_tenon_half_w, hang_width, 4);

arguments.new:
// Blade tenon below the shoulder: 24 x 34 with 3 mm 45 deg corner
// chamfers (not radii, so no near-horizontal surface floats above
// the bed-side face when printed on its side). It clears the post
// socket's 5 mm rounded corners and reaches 2 mm up into the neck
// so the union is volumetric, not face-only.
translate([0, 0, hang_width/2]) rotate([-90, 0, 0])
    linear_extrude(hang_shoulder_rel + 2)
        polygon([[-9, -17], [9, -17], [12, -14], [12, 14],
                 [9, 17], [-9, 17], [-12, 14], [-12, -14]]);
